class Settings:
    def __init__(self, api_key, base_url, timeout):
        self.api_key = api_key
        self.base_url = base_url
        self.timeout = timeout

    def __repr__(self):
        return f"Settings(base_url={self.base_url!r}, timeout={self.timeout}, api_key={mask(self.api_key)!r})"


def mask(secret):
    if len(secret) < 8:
        return "****"
    return "****" + secret[-4:]


def load_settings(env):
    key = env.get("BOOKS_API_KEY", "").strip()
    if not key:
        raise ValueError("BOOKS_API_KEY is not set")
    if len(key) < 8 or any(c.isspace() for c in key):
        raise ValueError("BOOKS_API_KEY is not valid")

    base_url = env.get("BOOKS_BASE_URL", "https://api.example.com/v1")
    if not base_url.startswith("https://"):
        raise ValueError("BOOKS_BASE_URL must use https")
    base_url = base_url.rstrip("/")

    timeout_text = env.get("BOOKS_TIMEOUT", "10")
    if not timeout_text.isdigit() or not 1 <= int(timeout_text) <= 120:
        raise ValueError("BOOKS_TIMEOUT must be a whole number from 1 to 120")

    return Settings(key, base_url, int(timeout_text))

unitTests:
def error(env):
    try:
        load_settings(env)
    except ValueError as e:
        return str(e)
    return None

@test("defaults")
def _():
    s = load_settings({"BOOKS_API_KEY": "  sk_test_12345678  "})
    check_eq((s.api_key, s.base_url, s.timeout), ("sk_test_12345678", "https://api.example.com/v1", 10))

@test("everything set")
def _():
    s = load_settings({"BOOKS_API_KEY": "sk_live_abcdwxyz", "BOOKS_BASE_URL": "https://books.test/v2/", "BOOKS_TIMEOUT": "30"})
    check_eq((s.base_url, s.timeout), ("https://books.test/v2", 30))

@test("a missing or bad key")
def _():
    check_eq(error({}), "BOOKS_API_KEY is not set")
    check_eq(error({"BOOKS_API_KEY": "   "}), "BOOKS_API_KEY is not set")
    check_eq(error({"BOOKS_API_KEY": "short"}), "BOOKS_API_KEY is not valid")
    message = error({"BOOKS_API_KEY": "sk_live_top secret"})
    check_eq(message, "BOOKS_API_KEY is not valid")
    check("top" not in message and "sk_live" not in message)

@test("other settings")
def _():
    key = {"BOOKS_API_KEY": "sk_test_12345678"}
    check_eq(error({**key, "BOOKS_BASE_URL": "http://api.example.com"}), "BOOKS_BASE_URL must use https")
    for bad in ("0", "121", "ten", "-5", "1.5", ""):
        check_eq(error({**key, "BOOKS_TIMEOUT": bad}), "BOOKS_TIMEOUT must be a whole number from 1 to 120")
    check_eq(load_settings({**key, "BOOKS_TIMEOUT": "120"}).timeout, 120)

@test("masking")
def _():
    check_eq(mask("sk_live_abcd1234"), "****1234")
    check_eq(mask("12345678"), "****5678")
    check_eq(mask("1234567"), "****")
    check_eq(mask(""), "****")

@test("the repr hides the key")
def _():
    s = load_settings({"BOOKS_API_KEY": "sk_live_secretvalue9876"})
    text = repr(s)
    check_eq(text, "Settings(base_url='https://api.example.com/v1', timeout=10, api_key='****9876')")
    check("secretvalue" not in text and "secretvalue" not in str(s))

